// Comprehensive mock data for the Travel Booking Platform

export type Role = 
  | "SUPER_ADMIN" 
  | "AGENCY_ADMIN"  // Previously CORPORATE_ADMIN
  | "AGENT"  // Previously EMPLOYEE
  | "SUB_AGENT"
  | "FINANCE_TEAM"
  | "SUPPORT_TEAM"
  | "KYC_COMPLIANCE_TEAM"

export interface User {
  id: string
  name: string
  email: string
  role: Role
  avatar: string
  department?: string
  policyId?: string
  walletBalance?: number
}

export interface Hotel {
  id: string
  name: string
  location: string
  rating: number
  pricePerNight: number
  currency: string
  image: string
  amenities: string[]
  description: string
  policyCompliant: boolean
}

export interface Flight {
  id: string
  airline: string
  airlineLogo: string
  flightNumber: string
  departure: {
    code: string
    city: string
    time: string
  }
  arrival: {
    code: string
    city: string
    time: string
  }
  duration: string
  price: number
  currency: string
  policyCompliant: boolean
  stops: number
}

export interface Booking {
  id: string
  type: "FLIGHT" | "HOTEL"
  status: "CONFIRMED" | "PENDING_APPROVAL" | "CANCELLED" | "COMPLETED" | "REFUNDED"
  details: any
  date: string
  amount: number
  employeeName: string
  employeeId: string
  approvalStatus?: "APPROVED" | "REJECTED" | "PENDING"
}

